ra_service_is_active() { if ra_capture systemctl is-active --quiet "$RA_SERVICE"; then return 0; fi; [[ "$RA_CAPTURE_RC" == 3 ]] && return 1; return 2; }
ra_lifecycle_graceful_restart() { local before; before="$(ra_main_pid)" || return 1; ra_state_jq '.scenarios.graceful_restart.private=((.scenarios.graceful_restart.private//{})+{before_pid:$pid,mutation_requested:true})' --argjson pid "$before" || return 1; ra_privacy_watch_start graceful_restart; ra_capture systemctl restart "$RA_SERVICE" || { ra_privacy_watch_cancel; return 1; }; ra_wait_new_pid "$before" >/dev/null || { ra_privacy_watch_cancel; return 1; }; ra_wait_active || { ra_privacy_watch_cancel; return 1; }; ra_privacy_watch_stop; }
ra_lifecycle_unexpected_death() { local before; before="$(ra_main_pid)" || return 1; ra_state_jq '.scenarios.daemon_kill.private=((.scenarios.daemon_kill.private//{})+{before_pid:$pid,mutation_requested:true})' --argjson pid "$before" || return 1; ra_privacy_watch_start daemon_kill; ra_capture systemctl kill --kill-who=main --signal=SIGKILL "$RA_SERVICE" || { ra_privacy_watch_cancel; return 1; }; ra_wait_new_pid "$before" >/dev/null || { ra_privacy_watch_cancel; return 1; }; ra_wait_active || { ra_privacy_watch_cancel; return 1; }; ra_privacy_watch_stop; }
ra_lifecycle_stop_start() { ra_state_jq '.scenarios.stop_start_no_reconnect.private=((.scenarios.stop_start_no_reconnect.private//{})+{stop_requested:true})' || return 1; ra_capture systemctl stop "$RA_SERVICE" || return 1; ra_state_jq '.scenarios.stop_start_no_reconnect.private.stop_completed=true' || return 1; ra_verify_inactive_boundary || return 1; ra_privacy_require_ordinary || return 1; ra_state_jq '.scenarios.stop_start_no_reconnect.private.start_requested=true' || return 1; ra_capture systemctl start "$RA_SERVICE" || return 1; ra_state_jq '.scenarios.stop_start_no_reconnect.private.start_completed=true' || return 1; ra_wait_inactive 90; }
ra_lifecycle_reinstall() { local candidate="$1" before identity; before="$(ra_main_pid)" || return 1; ra_state_jq '.scenarios.reinstall.private.before_pid=$pid' --argjson pid "$before" || return 1; identity="$(jq -cn --argjson c "$candidate" --argjson pid "$before" '{candidate:$c,before_pid:$pid}')" || return 1; ra_mut_begin_acquire reinstall_package candidate_package "$identity" || return 1; ra_privacy_watch_start reinstall; ra_pkg_install_exact "$candidate" || { ra_privacy_watch_cancel; return 1; }; ra_mut_mark_acquired reinstall_package || return 1; ra_state_jq '.scenarios.reinstall.private.dpkg_completed=true' || return 1; ra_wait_new_pid "$before" >/dev/null || return 1; ra_wait_active || return 1; ra_privacy_watch_stop || return 1; ra_mut_begin_release reinstall_package || return 1; ra_mut_mark_released reinstall_package; }
ra_wait_file() { local path="$1" deadline=$((SECONDS+$2)); while ((SECONDS<deadline)); do [[ -f "$path" && ! -L "$path" ]] && return 0; sleep 1; done; return 1; }
ra_rolling_back_authority_snapshot() { [[ -d "$RA_TRANSACTIONS" ]] || return 1; local count=0 path tx snapshot=""; while IFS= read -r -d '' path; do if jq -e '.owner=="podlaz" and .mode=="tun" and .state=="rolling_back" and (.id|type)=="string" and (.rollback|type)=="object" and ([.rollback.tun_addresses[]?,.rollback.routes[]?,.rollback.policy_rules[]?,.rollback.dns[]?,.rollback.nftables[]?,.rollback.generated_configs[]?,.rollback.child_processes[]?]|any(.owner=="podlaz"))' "$path" >/dev/null 2>&1; then ((count+=1)); tx="$(cat "$path")" || return 1; snapshot="$(jq -c --arg path "$path" '{transaction_id:.id,transaction_file:$path,state:.state,rollback:.rollback}' <<<"$tx")" || return 1; fi; done < <(find "$RA_TRANSACTIONS" -maxdepth 1 -type f -name '*.json' -print0 2>/dev/null); [[ "$count" == 1 ]] || return 1; printf '%s' "$snapshot"; }
ra_exact_rolling_back_count() { if ra_rolling_back_authority_snapshot >/dev/null 2>&1; then printf '1'; else printf '0'; fi; }
ra_lifecycle_rollback_interruption() { local profile="$1" content old restart_pid rolling_back_authority session_before session_after tx_id; ra_disconnect || return 1; ra_wait_inactive || return 1; ra_privacy_require_ordinary || return 1; printf -v content '[Service]\nEnvironment=PODLAZ_E2E_TUN_ROLLBACK_PAUSE=true\nEnvironment=PODLAZ_E2E_TUN_ROLLBACK_PAUSE_DIR=%s\nEnvironment=PODLAZ_E2E_TUN_ROLLBACK_PAUSE_TIMEOUT_SECONDS=180\n' "$RA_ROLLBACK_HOOK_DIR"; ra_systemd_hook_acquire rollback_hook "$RA_ROLLBACK_OVERRIDE" "$RA_ROLLBACK_HOOK_DIR" "$content" || return 1; ra_capture systemctl restart "$RA_SERVICE" || return 1; ra_wait_inactive || return 1; ra_connect "$profile" || return 1; ra_wait_active || return 1; ra_privacy_require_protected || return 1; session_before="$(ra_network_session_snapshot)" || return 1; printf 'armed\n' >"$RA_ROLLBACK_HOOK_DIR/rollback-pause.arm" || return 1; old="$(ra_main_pid)" || return 1; ra_privacy_watch_start rollback; systemctl restart "$RA_SERVICE" >>"$RA_TRANSCRIPT" 2>&1 & restart_pid=$!; RA_BACKGROUND_PID="$restart_pid"; ra_wait_file "$RA_ROLLBACK_HOOK_DIR/rollback-pause.ready" 60 || return 1; rolling_back_authority="$(ra_rolling_back_authority_snapshot)" || { ra_die "ownership exact rolling_back transaction authority unavailable"; return 1; }; tx_id="$(jq -r '.transaction_id' <<<"$rolling_back_authority")"; ra_state_jq '.scenarios.rollback_interruption.private=((.scenarios.rollback_interruption.private//{})+{rolling_back_authority:$authority,session_before:$session})' --argjson authority "$rolling_back_authority" --argjson session "$session_before" || return 1; sync -f "$RA_CHECKPOINT" 2>/dev/null || true; ra_capture kill -KILL "$old" || return 1; wait "$restart_pid" || true; RA_BACKGROUND_PID=""; ra_wait_new_pid "$old" 120 >/dev/null || return 1; ra_wait_active 180 || return 1; session_after="$(ra_network_session_snapshot)" || return 1; [[ "$(jq -r '.session_id' <<<"$session_after")" == "$(jq -r '.session_id' <<<"$session_before")" ]] || { ra_die "product rollback replacement changed Network Session"; return 1; }; if [[ -f "$RA_TRANSACTIONS/$tx_id.json" ]]; then jq -e '.state!="rolling_back"' "$RA_TRANSACTIONS/$tx_id.json" >/dev/null || return 1; fi; ra_state_jq '.scenarios.rollback_interruption.private.session_after=$session' --argjson session "$session_after" || return 1; ra_privacy_watch_stop || return 1; ra_systemd_hook_cleanup rollback_hook; }

ra_runtime_terminal_failure() { local profile="$1" content before; ra_wait_inactive || return 1; ra_privacy_require_ordinary || return 1; printf -v content '[Service]\nEnvironment=PODLAZ_E2E_TUN_TERMINAL_FAILURE=true\nEnvironment=PODLAZ_E2E_TUN_TERMINAL_FAILURE_DIR=%s\nEnvironment=PODLAZ_E2E_PRIVACY_TEARDOWN_PAUSE=true\nEnvironment=PODLAZ_E2E_PRIVACY_TEARDOWN_PAUSE_DIR=%s\nEnvironment=PODLAZ_E2E_PRIVACY_TEARDOWN_PAUSE_TIMEOUT_SECONDS=180\n' "$RA_TERMINAL_HOOK_DIR" "$RA_TERMINAL_HOOK_DIR"; ra_systemd_hook_acquire terminal_hook "$RA_TERMINAL_OVERRIDE" "$RA_TERMINAL_HOOK_DIR" "$content" || return 1; ra_capture systemctl restart "$RA_SERVICE" || return 1; ra_wait_inactive || return 1; ra_connect "$profile" || return 1; ra_wait_active || return 1; ra_privacy_require_protected || return 1; printf 'trigger\n' >"$RA_TERMINAL_HOOK_DIR/terminal-failure.trigger" || return 1; ra_wait_file "$RA_TERMINAL_HOOK_DIR/terminal-data-plane-clean.ready" 90 || return 1; ra_privacy_require_protected || return 1; printf 'continue\n' >"$RA_TERMINAL_HOOK_DIR/terminal-data-plane-clean.continue" || return 1; ra_wait_inactive 120 || return 1; ra_systemd_hook_cleanup terminal_hook || return 1; ra_privacy_require_ordinary || return 1; before="$(ra_main_pid)" || return 1; ra_capture systemctl restart "$RA_SERVICE" || return 1; ra_wait_new_pid "$before" >/dev/null || return 1; ra_wait_inactive 30; }

# Package mutation protocols.
ra_package_setup_prepare() { local candidate="$1" previous="$2" installed="$3" cv pv identity; cv="$(jq -r '.version' <<<"$candidate")" || return 1; if [[ -n "$installed" ]] && ra_pkg_gt "$installed" "$cv"; then ra_preflight_die "installed Podlaz version is newer than candidate; refusing downgrade"; return 2; fi; if [[ -n "$installed" && "$installed" != "$cv" ]] && ra_pkg_lt "$installed" "$cv"; then return 0; fi; [[ -n "$previous" ]] || { ra_die "input full lower-release qualification requires --previous-deb"; return 1; }; pv="$(jq -r '.version' <<<"$previous")" || return 1; ra_pkg_lt "$pv" "$cv" || return 1; identity="$(jq -cn --argjson p "$previous" --argjson c "$candidate" '{previous:$p,candidate:$c}')" || return 1; ra_mut_begin_acquire package_setup previous_package "$identity" || return 1; ra_pkg_install_exact "$previous" || return 1; ra_wait_inactive 90 || return 1; ra_mut_mark_acquired package_setup; }
ra_package_setup_resume_prepare() { local candidate="$1" previous="$2" installed cv state pre pv identity; cv="$(jq -r '.version' <<<"$candidate")" || return 1; installed="$(ra_pkg_installed_version)" || return 1; if ! jq -e '.mutations.package_setup' "$RA_CHECKPOINT" >/dev/null 2>&1; then if [[ -n "$installed" && "$installed" != "$cv" ]] && ra_pkg_lt "$installed" "$cv"; then return 0; fi; [[ -n "$previous" ]] || return 1; pv="$(jq -r '.version' <<<"$previous")" || return 1; pre="$(jq -r '.private.installed_before//""' "$RA_CHECKPOINT")" || return 1; [[ "$installed" == "$pre" ]] || return 1; identity="$(jq -cn --argjson p "$previous" --argjson c "$candidate" '{previous:$p,candidate:$c}')" || return 1; ra_mut_begin_acquire package_setup previous_package "$identity" || return 1; ra_pkg_install_exact "$previous" || return 1; ra_wait_inactive 90 || return 1; ra_mut_mark_acquired package_setup; return 0; fi; state="$(jq -r '.mutations.package_setup.state' "$RA_CHECKPOINT")"; pv="$(jq -r '.mutations.package_setup.identity.previous.version' "$RA_CHECKPOINT")"; case "$state" in acquiring) if [[ "$installed" == "$pv" ]]; then ra_mut_mark_acquired package_setup; return $?; fi; pre="$(jq -r '.private.installed_before//""' "$RA_CHECKPOINT")"; if [[ "$installed" == "$pre" ]]; then ra_die "ownership cannot prove whether interrupted lower-release installation ran"; return 1; fi; return 1 ;; acquired) [[ "$installed" == "$pv" ]] || return 1 ;; *) return 1 ;; esac; }
ra_package_setup_reconcile_abort() { local state identity candidate installed cv pv; state="$(jq -r '.mutations.package_setup.state//"released"' "$RA_CHECKPOINT")" || return 1; [[ "$state" != released ]] || return 0; identity="$(jq -ce '.mutations.package_setup.identity' "$RA_CHECKPOINT")" || return 1; candidate="$(jq -c '.candidate' <<<"$identity")"; cv="$(jq -r '.candidate.version' <<<"$identity")"; pv="$(jq -r '.previous.version' <<<"$identity")"; installed="$(ra_pkg_installed_version)" || return 1; if [[ "$installed" == "$cv" ]]; then if [[ "$state" == acquired ]]; then ra_mut_begin_release package_setup || return 1; fi; state="$(jq -r '.mutations.package_setup.state' "$RA_CHECKPOINT")"; if [[ "$state" == acquiring || "$state" == releasing ]]; then ra_mut_mark_released package_setup; fi; return 0; fi; [[ "$installed" == "$pv" ]] || { ra_die "ownership package_setup version ambiguous"; return 1; }; if [[ "$state" == acquiring ]]; then ra_mut_mark_acquired package_setup || return 1; fi; state="$(jq -r '.mutations.package_setup.state' "$RA_CHECKPOINT")"; [[ "$state" != acquired ]] || ra_mut_begin_release package_setup || return 1; ra_pkg_assert_identity "$candidate" || return 1; ra_pkg_install_exact "$candidate" || return 1; ra_wait_inactive 90 || return 1; ra_mut_mark_released package_setup; }
ra_package_setup_release_after_candidate() { local state installed cv; state="$(jq -r '.mutations.package_setup.state//"released"' "$RA_CHECKPOINT")" || return 1; [[ "$state" != released ]] || return 0; installed="$(ra_pkg_installed_version)" || return 1; cv="$(jq -r '.candidate.version' "$RA_CHECKPOINT")" || return 1; [[ "$installed" == "$cv" ]] || return 1; if [[ "$state" == acquired ]]; then ra_mut_begin_release package_setup || return 1; elif [[ "$state" != acquiring && "$state" != releasing ]]; then return 1; fi; ra_mut_mark_released package_setup; }
ra_candidate_upgrade_begin() { local candidate="$1" installed="$2" identity; identity="$(jq -cn --argjson c "$candidate" --arg installed "$installed" '{candidate:$c,installed_before:$installed,applied:false}')" || return 1; ra_mut_begin_acquire candidate_upgrade candidate_package "$identity"; }
ra_candidate_upgrade_reconcile_cleanup() { local state candidate before installed cv; state="$(jq -r '.mutations.candidate_upgrade.state//"released"' "$RA_CHECKPOINT")" || return 1; [[ "$state" != released ]] || return 0; candidate="$(jq -ce '.mutations.candidate_upgrade.identity.candidate' "$RA_CHECKPOINT")" || return 1; before="$(jq -r '.mutations.candidate_upgrade.identity.installed_before' "$RA_CHECKPOINT")"; cv="$(jq -r '.version' <<<"$candidate")"; installed="$(ra_pkg_installed_version)" || return 1; if [[ "$installed" == "$cv" ]]; then ra_state_jq '.mutations.candidate_upgrade.identity.applied=true' || return 1; if [[ "$state" == acquiring ]]; then ra_mut_mark_acquired candidate_upgrade || return 1; state=acquired; fi; [[ "$state" != acquired ]] || ra_mut_begin_release candidate_upgrade || return 1; ra_mut_mark_released candidate_upgrade; return 0; fi; if [[ "$installed" == "$before" && "$state" == acquiring ]]; then ra_state_jq '.mutations.candidate_upgrade.identity.applied=false' || return 1; ra_mut_mark_released candidate_upgrade; return 0; fi; ra_die "ownership candidate upgrade package state ambiguous"; return 1; }
ra_reinstall_package_reconcile_cleanup() { local state candidate installed cv before current; state="$(jq -r '.mutations.reinstall_package.state//"released"' "$RA_CHECKPOINT")" || return 1; [[ "$state" != released ]] || return 0; candidate="$(jq -ce '.mutations.reinstall_package.identity.candidate' "$RA_CHECKPOINT")" || return 1; cv="$(jq -r '.version' <<<"$candidate")"; installed="$(ra_pkg_installed_version)" || return 1; [[ "$installed" == "$cv" ]] || return 1; if [[ "$state" == acquiring ]]; then before="$(jq -r '.mutations.reinstall_package.identity.before_pid' "$RA_CHECKPOINT")"; current="$(ra_main_pid 2>/dev/null || true)"; [[ -n "$current" && "$current" != "$before" ]] || { ra_die "ownership cannot prove interrupted same-candidate reinstall"; return 1; }; ra_mut_mark_acquired reinstall_package || return 1; state=acquired; fi; [[ "$state" != acquired ]] || ra_mut_begin_release reinstall_package || return 1; ra_mut_mark_released reinstall_package; }

ra_terminal_profile_is_exact() { ra_product profile show "$1" --json || return 1; jq -e --arg name "$RA_TERMINAL_NAME" '.schema_version=="v1" and .status=="ok" and .profile.name==$name and .profile.server=="vpn.invalid" and (.profile.port|tonumber)==443 and (.profile.protocol|ascii_downcase)=="vless"' <<<"$RA_CAPTURE" >/dev/null; }
ra_terminal_profile_ensure() { local acq state baseline current additions id imported; acq="$(jq -ce '.private.terminal_profile_acquisition//empty' "$RA_CHECKPOINT" 2>/dev/null || true)"; if [[ -z "$acq" ]]; then baseline="$(ra_profile_ids_json)" || return 1; ra_state_jq '.private.terminal_profile_acquisition={state:"prepared",baseline_ids:$ids}' --argjson ids "$baseline" || return 1; acq="$(jq -ce '.private.terminal_profile_acquisition' "$RA_CHECKPOINT")" || return 1; fi; state="$(jq -r '.state' <<<"$acq")"; baseline="$(jq -c '.baseline_ids' <<<"$acq")"; case "$state" in prepared) current="$(ra_profile_ids_json)" || return 1; [[ "$(jq -cS . <<<"$current")" == "$(jq -cS . <<<"$baseline")" ]] || return 1; ra_state_jq '.private.terminal_profile_acquisition.state="acquiring"' || return 1; ra_product profile import "$RA_TERMINAL_URI" || return 1; imported="$(sed -n 's/^Imported profile:[[:space:]]*//p' <<<"$RA_CAPTURE" | head -n1)"; current="$(ra_profile_ids_json)" || return 1; additions="$(jq -cn --argjson a "$current" --argjson b "$baseline" '$a-$b')"; [[ "$(jq length <<<"$additions")" == 1 ]] || return 1; id="$(jq -r '.[0]' <<<"$additions")"; [[ -z "$imported" || "$imported" == "$id" ]] || return 1; ra_terminal_profile_is_exact "$id" || return 1; ra_state_jq '.private.terminal_profile=$id|.private.terminal_profile_acquisition.state="acquired"|.private.terminal_profile_acquisition.profile_id=$id' --arg id "$id" || return 1; printf '%s' "$id" ;; acquiring) current="$(ra_profile_ids_json)" || return 1; additions="$(jq -cn --argjson a "$current" --argjson b "$baseline" '$a-$b')"; [[ "$(jq length <<<"$additions")" == 1 ]] || { ra_die "ownership terminal profile acquisition ambiguous"; return 1; }; id="$(jq -r '.[0]' <<<"$additions")"; ra_terminal_profile_is_exact "$id" || return 1; ra_state_jq '.private.terminal_profile=$id|.private.terminal_profile_acquisition.state="acquired"|.private.terminal_profile_acquisition.profile_id=$id' --arg id "$id" || return 1; printf '%s' "$id" ;; acquired) id="$(jq -r '.profile_id' <<<"$acq")"; current="$(ra_profile_ids_json)" || return 1; jq -e --arg id "$id" 'index($id)!=null' <<<"$current" >/dev/null || return 1; ra_terminal_profile_is_exact "$id" || return 1; printf '%s' "$id" ;; *) return 1 ;; esac; }
ra_terminal_profile_create() { ra_terminal_profile_ensure; }
ra_terminal_profile_reconcile() { local acq state baseline current additions id; acq="$(jq -ce '.private.terminal_profile_acquisition//empty' "$RA_CHECKPOINT" 2>/dev/null || true)"; [[ -n "$acq" ]] || return 0; state="$(jq -r '.state' <<<"$acq")"; baseline="$(jq -c '.baseline_ids' <<<"$acq")"; current="$(ra_profile_ids_json)" || return 1; case "$state" in prepared) [[ "$(jq -cS . <<<"$current")" == "$(jq -cS . <<<"$baseline")" ]] || return 1; ra_state_jq 'del(.private.terminal_profile_acquisition)'; return $? ;; acquiring) additions="$(jq -cn --argjson a "$current" --argjson b "$baseline" '$a-$b')"; if [[ "$(jq length <<<"$additions")" == 0 ]]; then ra_state_jq 'del(.private.terminal_profile_acquisition)'; return $?; fi; [[ "$(jq length <<<"$additions")" == 1 ]] || return 1; id="$(jq -r '.[0]' <<<"$additions")"; ra_terminal_profile_is_exact "$id" || return 1; ra_state_jq '.private.terminal_profile=$id|.private.terminal_profile_acquisition.state="acquired"|.private.terminal_profile_acquisition.profile_id=$id' --arg id "$id" || return 1 ;; acquired|releasing) id="$(jq -r '.profile_id' <<<"$acq")" ;; *) return 1 ;; esac; current="$(ra_profile_ids_json)" || return 1; if jq -e --arg id "$id" 'index($id)!=null' <<<"$current" >/dev/null; then ra_terminal_profile_is_exact "$id" || return 1; if [[ "$state" != releasing ]]; then ra_state_jq '.private.terminal_profile_acquisition.state="releasing"' || return 1; fi; ra_product profile delete "$id" --yes || return 1; fi; current="$(ra_profile_ids_json)" || return 1; jq -e --arg id "$id" --argjson baseline "$baseline" 'index($id)==null and (sort==($baseline|sort))' <<<"$current" >/dev/null || { ra_die "ownership synthetic terminal profile deletion was not exact"; return 1; }; ra_state_jq 'del(.private.terminal_profile,.private.terminal_profile_acquisition)'; }

ra_autostart_set_owned() { local name="$1" action="$2" profile="${3:-}" pre post identity; pre="$(ra_boot_manifest_capture)" || return 1; if ra_boot_manifest_semantic_matches "$action" "$profile"; then return 0; fi; identity="$(jq -cn --arg action "$action" --arg profile "$profile" --argjson pre "$pre" '{action:$action,profile:$profile,pre_manifest:$pre}')" || return 1; ra_mut_begin_acquire "$name" autostart_policy "$identity" || return 1; if [[ "$action" == disable ]]; then ra_product autostart disable >/dev/null || return 1; else ra_product autostart enable --mode tun "$profile" >/dev/null || return 1; fi; post="$(ra_boot_manifest_capture)" || return 1; ra_state_jq '.mutations[$n].identity.owned_manifest=$post' --arg n "$name" --argjson post "$post" || return 1; ra_mut_mark_acquired "$name"; }
ra_autostart_ensure_owned() { local name="$1" action="$2" profile="${3:-}" state pre owned post; state="$(jq -r --arg n "$name" '.mutations[$n].state//"released"' "$RA_CHECKPOINT")" || return 1; if [[ "$state" == released ]]; then ra_autostart_set_owned "$name" "$action" "$profile"; return $?; fi; pre="$(jq -ce --arg n "$name" '.mutations[$n].identity.pre_manifest' "$RA_CHECKPOINT")" || return 1; owned="$(jq -ce --arg n "$name" '.mutations[$n].identity.owned_manifest//empty' "$RA_CHECKPOINT" 2>/dev/null || true)"; case "$state" in acquiring) if [[ -n "$owned" ]] && ra_manifest_matches_snapshot "$owned"; then ra_mut_mark_acquired "$name"; return $?; fi; if ra_manifest_matches_snapshot "$pre"; then ra_die "ownership cannot prove interrupted autostart mutation"; return 1; fi; if ra_boot_manifest_semantic_matches "$action" "$profile"; then post="$(ra_boot_manifest_capture)" || return 1; ra_state_jq '.mutations[$n].identity.owned_manifest=$post' --arg n "$name" --argjson post "$post" || return 1; ra_mut_mark_acquired "$name"; return $?; fi; return 1 ;; acquired) [[ -n "$owned" ]] && ra_manifest_matches_snapshot "$owned" || return 1 ;; *) return 1 ;; esac; }
ra_autostart_release_owned() { local name="$1" state pre owned action profile; state="$(jq -r --arg n "$name" '.mutations[$n].state//"released"' "$RA_CHECKPOINT")" || return 1; [[ "$state" != released ]] || return 0; pre="$(jq -ce --arg n "$name" '.mutations[$n].identity.pre_manifest' "$RA_CHECKPOINT")" || return 1; owned="$(jq -ce --arg n "$name" '.mutations[$n].identity.owned_manifest//empty' "$RA_CHECKPOINT" 2>/dev/null || true)"; if [[ "$state" == acquiring ]]; then if ra_manifest_matches_snapshot "$pre"; then ra_mut_mark_released "$name"; return 0; fi; if [[ -n "$owned" ]] && ra_manifest_matches_snapshot "$owned"; then ra_mut_mark_acquired "$name" || return 1; state=acquired; else action="$(jq -r --arg n "$name" '.mutations[$n].identity.action' "$RA_CHECKPOINT")"; profile="$(jq -r --arg n "$name" '.mutations[$n].identity.profile//""' "$RA_CHECKPOINT")"; if ra_boot_manifest_semantic_matches "$action" "$profile"; then owned="$(ra_boot_manifest_capture)" || return 1; ra_state_jq '.mutations[$n].identity.owned_manifest=$post' --arg n "$name" --argjson post "$owned" || return 1; ra_mut_mark_acquired "$name" || return 1; state=acquired; else return 1; fi; fi; fi; if [[ "$state" == acquired ]]; then [[ -n "$owned" ]] && ra_manifest_matches_snapshot "$owned" || return 1; ra_mut_begin_release "$name" || return 1; state=releasing; fi; if [[ "$state" == releasing ]]; then if ra_manifest_matches_snapshot "$pre"; then ra_mut_mark_released "$name"; return 0; fi; [[ -n "$owned" ]] && ra_manifest_matches_snapshot "$owned" || return 1; ra_boot_manifest_restore "$pre" || return 1; ra_manifest_matches_snapshot "$pre" || return 1; ra_mut_mark_released "$name"; fi; }
ra_restore_original_policy() { local entries name state original; entries="$(jq -r '.mutations|to_entries|reverse[]|select(.value.kind=="autostart_policy")|[.key,.value.state]|@tsv' "$RA_CHECKPOINT")" || return 1; while IFS=$'\t' read -r name state; do [[ -n "$name" && "$state" != released ]] || continue; ra_autostart_release_owned "$name" || return 1; done <<<"$entries"; ra_terminal_profile_reconcile || return 1; original="$(jq -ce '.private.boot_manifest' "$RA_CHECKPOINT")" || return 1; ra_manifest_matches_snapshot "$original" || { ra_die "ownership original autostart manifest not restored"; return 1; }; }

ra_cleanup_owned_mutations() { local entries name kind state; entries="$(jq -r '.mutations|to_entries|reverse[]|[.key,.value.kind,.value.state]|@tsv' "$RA_CHECKPOINT")" || return 1; while IFS=$'\t' read -r name kind state; do [[ -n "$name" && "$state" != released ]] || continue; case "$kind" in previous_package|candidate_package|autostart_policy) ;; network_fixture) ra_fixture_release "$name" || return 1 ;; systemd_dropin) ra_systemd_hook_cleanup "$name" || return 1 ;; networkmanager_connection) ra_nm_reconcile "$name" || return 1 ;; *) ra_die "internal unsupported owned mutation kind: $kind"; return 1 ;; esac; done <<<"$entries"; }
ra_require_mutations_released() { local pending; pending="$(jq -r '[.mutations|to_entries[]|select(.value.state!="released")|.key]|join(",")' "$RA_CHECKPOINT")" || return 1; [[ -z "$pending" ]] || { ra_die "ownership mutation cleanup incomplete: $pending"; return 1; }; }
ra_session_observe() { local payload cleanup active_id committed rc selected profile_id; selected="$(jq -r '.private.selected_profile//.private.run_config.profile//""' "$RA_CHECKPOINT" 2>/dev/null || true)"; if payload="$(ra_status_json 2>/dev/null)"; then cleanup="$(jq '[.transactions[]?|select((.requires_cleanup//false)==true)]|length' <<<"$payload" 2>/dev/null)" || { printf ambiguous; return 0; }; active_id="$(jq -r '.active_transaction_id//""' <<<"$payload" 2>/dev/null)" || { printf ambiguous; return 0; }; committed="$(jq '[.transactions[]?|select(.state=="committed" and (.requires_cleanup//false)==false)]|length' <<<"$payload" 2>/dev/null)" || { printf ambiguous; return 0; }; profile_id="$(jq -r '.profile_id//""' <<<"$payload" 2>/dev/null)" || { printf ambiguous; return 0; }; if [[ "$(jq -r '.connection//""' <<<"$payload")" == active && "$(jq -r '.mode//""' <<<"$payload")" == tun && "$committed" -gt 0 ]]; then [[ -n "$selected" && "$profile_id" == "$selected" ]] || { printf ambiguous; return 0; }; printf active; return 0; fi; if [[ "$(jq -r '.connection//""' <<<"$payload")" == inactive && "$cleanup" == 0 && -z "$active_id" && "$committed" == 0 ]]; then printf inactive; return 0; fi; printf ambiguous; return 0; else rc=$?; ((rc!=2)) || { printf ambiguous; return 0; }; fi; if [[ -e "$RA_CONTINUATION" || -L "$RA_CONTINUATION" ]]; then printf ambiguous; return 0; fi; if [[ -d "$RA_TRANSACTIONS" ]]; then local path; while IFS= read -r -d '' path; do if ! jq -e '(.requires_cleanup//false)==false and (.state!="committed") and (.state!="rolling_back") and (.state!="applying") and (.state!="verifying")' "$path" >/dev/null 2>&1; then printf ambiguous; return 0; fi; done < <(find "$RA_TRANSACTIONS" -maxdepth 1 -type f -name '*.json' -print0 2>/dev/null); fi; printf inactive; }
ra_safe_disconnect_if_owned() { local observed; observed="$(ra_session_observe)" || return 1; case "$observed" in inactive) return 0 ;; active) ra_disconnect || return 1; ra_wait_inactive 120 || return 1 ;; *) ra_die "ownership acceptance session ambiguous; refusing cleanup"; return 1 ;; esac; }
ra_verify_inactive_boundary() { local observed; observed="$(ra_session_observe)" || return 1; [[ "$observed" == inactive ]] || { ra_die "product Podlaz is not conclusively inactive"; return 1; }; }
ra_package_cleanup_reconcile() { if jq -e '.mutations.candidate_upgrade and .mutations.candidate_upgrade.state!="released"' "$RA_CHECKPOINT" >/dev/null 2>&1; then ra_candidate_upgrade_reconcile_cleanup || return 1; fi; if jq -e '.mutations.reinstall_package and .mutations.reinstall_package.state!="released"' "$RA_CHECKPOINT" >/dev/null 2>&1; then ra_reinstall_package_reconcile_cleanup || return 1; fi; if jq -e '.mutations.package_setup and .mutations.package_setup.state!="released"' "$RA_CHECKPOINT" >/dev/null 2>&1; then ra_package_setup_reconcile_abort || return 1; fi; }
ra_cleanup_expected_package_version() { local installed initial candidate cv require_candidate=false; installed="$(ra_pkg_installed_version)" || return 1; initial="$(jq -r '.private.installed_before//""' "$RA_CHECKPOINT")"; candidate="$(jq -ce '.candidate' "$RA_CHECKPOINT")" || return 1; cv="$(jq -r '.version' <<<"$candidate")"; if jq -e '.mutations.package_setup' "$RA_CHECKPOINT" >/dev/null 2>&1; then require_candidate=true; fi; if jq -e '.mutations.reinstall_package' "$RA_CHECKPOINT" >/dev/null 2>&1; then require_candidate=true; fi; if [[ "$(jq -r '.mutations.candidate_upgrade.identity.applied//false' "$RA_CHECKPOINT")" == true ]]; then require_candidate=true; fi; if [[ "$require_candidate" == true ]]; then printf '%s' "$cv"; return 0; fi; [[ "$installed" == "$cv" || "$installed" == "$initial" ]] || return 1; printf '%s' "$installed"; }
ra_cleanup_expected_package_verify() { local installed expected; installed="$(ra_pkg_installed_version)" || return 1; expected="$(ra_cleanup_expected_package_version)" || return 1; [[ "$installed" == "$expected" ]] || return 1; }
ra_restore_service_state() { local wanted rc; wanted="$(jq -r '.private.service_active_before' "$RA_CHECKPOINT")" || return 1; if ra_service_is_active; then rc=0; else rc=$?; fi; [[ "$rc" == 0 || "$rc" == 1 ]] || { ra_die "host_state service active state ambiguous"; return 1; }; if [[ "$wanted" == true && "$rc" == 1 ]]; then ra_capture systemctl start "$RA_SERVICE" || return 1; ra_service_is_active || return 1; elif [[ "$wanted" == false && "$rc" == 0 ]]; then ra_capture systemctl stop "$RA_SERVICE" || return 1; if ra_service_is_active; then return 1; else [[ "$?" == 1 ]] || return 1; fi; fi; }
ra_verify_run_tree() { local run_root path mode uid gid; run_root="$(dirname "$RA_PRIVATE_DIR")"; [[ -d "$run_root" && ! -L "$run_root" ]] || return 1; while IFS= read -r -d '' path; do [[ ! -L "$path" ]] || return 1; uid="$(stat -Lc '%u' "$path")" || return 1; gid="$(stat -Lc '%g' "$path")" || return 1; [[ "$uid" == "$RA_UID" && "$gid" == "$RA_GID" ]] || return 1; if [[ -d "$path" ]]; then mode="$(stat -Lc '%a' "$path")" || return 1; [[ "$mode" == 700 ]] || return 1; elif [[ "$path" == "$RA_PRIVATE_DIR"/* ]]; then mode="$(stat -Lc '%a' "$path")" || return 1; [[ "$mode" == 600 ]] || return 1; else mode="$(stat -Lc '%a' "$path")" || return 1; (((8#$mode & 0022) == 0)) || return 1; fi; done < <(find "$run_root" -mindepth 0 -print0); if [[ "${RELEASE_ACCEPTANCE_TEST_MODE:-0}" != 1 ]]; then [[ "$(stat -Lc '%u:%g:%a' "$RA_STATE_DIR")" == "0:0:700" ]] || return 1; [[ "$(stat -Lc '%u:%g:%a' "$RA_CHECKPOINT")" == "0:0:600" ]] || return 1; fi; }
ra_safe_cleanup() { ra_privacy_watch_cancel; ra_safe_disconnect_if_owned || return 1; ra_cleanup_owned_mutations || return 1; ra_restore_original_policy || return 1; ra_package_cleanup_reconcile || return 1; ra_cleanup_expected_package_verify || return 1; ra_require_mutations_released || return 1; ra_verify_inactive_boundary || return 1; ra_privacy_require_ordinary || return 1; [[ ! -e "$RA_ROLLBACK_OVERRIDE" && ! -L "$RA_ROLLBACK_OVERRIDE" && ! -e "$RA_TERMINAL_OVERRIDE" && ! -L "$RA_TERMINAL_OVERRIDE" && ! -e "$RA_ROLLBACK_HOOK_DIR" && ! -e "$RA_TERMINAL_HOOK_DIR" ]] || { ra_die "ownership acceptance hooks remain after cleanup"; return 1; }; ra_restore_service_state || return 1; ra_verify_run_tree || return 1; }
